    async function saveNewClassFromModal(){
      const name=(document.getElementById('newClassName')?.value||'').trim();
      if(!name){toast('Nhập tên lớp');return}
      if(classNameExists(name)){toast('Tên lớp đã tồn tại. Vui lòng chọn tên khác.');return}
      const teacher=document.getElementById('newTeacher')?.value||'';
      const ta=(document.getElementById('newTA')?.value||'').trim();
      const startDate=document.getElementById('newStartDate')?.value || isoDate(firstUpcomingDateFromForm());
      try{
        const data=await officialFetch('/api/classes',{method:'POST',body:JSON.stringify({
          name,
          teacherName:teacher,
          assistantName:ta,
          startDate,
          schedules:schedulePayloadFromNewClassForm()
        })});
        db.classes.push(data.class);
        save(); closeModal(); route='classes'; saveUser(); render(); toast(`Đã tạo ${name}.`);
      }catch(e){toast(e.message||'Không tạo được lớp')}
    }

    function modal(html){modalBackdrop.innerHTML=`<div class="modal">${html}</div>`;modalBackdrop.classList.add('show')}
    function closeModal(){modalBackdrop.classList.remove('show')}
    function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
    window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
    ensureLifecycle();
    bootstrapOfficial();
    setInterval(()=>{ if(currentUser && route==='schedule' && !document.getElementById('modalBackdrop')?.classList.contains('show')) renderApp(); }, 30000);
